import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseJsonResponse } from '../src/llm/jsonParser';

/**
 * Replays fixtures generated by fixtures/gen_jsonparse_fixture.py through the
 * TypeScript port. The fixture pins the behavior of the Python reference
 * implementation (utils/llm_client.py::LLMClient.parse_json_response) — if
 * either side changes without regenerating, this test fails.
 */

interface StrictCase {
  name: string;
  input: string;
  ok: boolean;
  value?: unknown;
  error_type?: string;
}

interface LenientCase {
  name: string;
  input: string;
  ts_value: unknown;
  python_error_type: string | null;
}

const fixture = JSON.parse(
  readFileSync(fileURLToPath(new URL('./fixtures/jsonparse_fixture.json', import.meta.url)), 'utf-8'),
) as { cases: StrictCase[]; lenient_cases: LenientCase[] };

describe('jsonParser parity with the Python reference', () => {
  it('fixture is populated', () => {
    expect(fixture.cases.length).toBeGreaterThanOrEqual(10);
    expect(fixture.cases.filter((c) => c.ok).length).toBeGreaterThan(0);
    expect(fixture.cases.filter((c) => !c.ok).length).toBeGreaterThan(0);
  });

  for (const c of fixture.cases) {
    it(`${c.name} (${c.ok ? 'parses' : c.error_type})`, () => {
      if (c.ok) {
        expect(parseJsonResponse(c.input)).toEqual(c.value);
      } else {
        expect(() => parseJsonResponse(c.input)).toThrow();
      }
    });
  }

  describe('documented deviations — the port is intentionally more lenient', () => {
    for (const c of fixture.lenient_cases) {
      it(`${c.name}: Python raises, port succeeds`, () => {
        expect(c.python_error_type).toBeTruthy();
        expect(parseJsonResponse(c.input)).toEqual(c.ts_value);
      });
    }
  });
});
